?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> | IRONCORE</title><link rel="stylesheet" href="/assets/css/style.css"><link rel="stylesheet" href="/assets/css/dashboard.css"><link rel="stylesheet" href="/assets/css/responsive.css"><style>.module-toolbar{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:20px}.module-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:14px;margin-bottom:20px}.module-stat{padding:20px}.module-stat strong{display:block;font-size:28px;margin-top:6px}.module-table{width:100%;border-collapse:collapse}.module-table th,.module-table td{padding:12px;text-align:left;border-bottom:1px solid rgba(255,255,255,.08)}.module-form{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;margin-bottom:20px}.module-form input,.module-form select,.module-form textarea{width:100%;padding:11px;background:var(--color-bg);border:1px solid rgba(255,255,255,.12);color:inherit;border-radius:6px}.module-form textarea{min-height:80px}.full{grid-column:1/-1}@media(max-width:700px){.module-table{font-size:12px}.module-table th:nth-child(n+5),.module-table td:nth-child(n+5){display:none}}</style></head><body style="background:var(--color-bg)"><div class="dashboard-shell"><div class="sidebar-overlay"></div><aside class="sidebar"><div class="sidebar-brand"><a href="/index.php" class="brand-logo"><span>IRONCORE</span></a><span class="sidebar-badge">ADMINISTRATOR CONTROL</span></div><ul class="sidebar-nav"><li><a href="/admin/index.php" class="nav-item-link">Dashboard</a></li><li><a href="/admin/members.php" class="nav-item-link">Members</a></li><li><a href="/admin/trainers.php" class="nav-item-link <?= $module==='trainers'?'active':''?>">Trainers</a></li><li><a href="/admin/memberships.php" class="nav-item-link <?= $module==='memberships'?'active':''?>">Memberships</a></li><li><a href="/admin/attendance.php" class="nav-item-link <?= $module==='attendance'?'active':''?>">Attendance</a></li><li><a href="/admin/payments.php" class="nav-item-link <?= $module==='payments'?'active':''?>">Payments</a></li><li><a href="/admin/workouts.php" class="nav-item-link <?= $module==='workouts'?'active':''?>">Workouts</a></li><li><a href="/admin/reports.php" class="nav-item-link <?= $module==='reports'?'active':''?>">Reports</a></li></ul><div class="sidebar-footer"><a href="/logout.php" class="btn btn-primary" style="width:100%;justify-content:center">Logout</a></div></aside><div class="main-wrapper"><header class="dashboard-header"><div><h1><?=e($title)?></h1><p>Live operational data and management controls.</p></div></header><main class="dashboard-body"><div id="stats" class="module-grid"></div><section class="panel-card"><div class="module-toolbar"><input id="search" class="form-control" placeholder="Search..." style="max-width:320px"><button id="refresh" class="btn btn-secondary">Refresh</button><button id="toggleForm" class="btn btn-primary">+ Add</button></div><form id="form" class="module-form" style="display:none"><input type="hidden" name="csrf_token" value="<?=e($csrf)?>"><div id="fields" class="module-form full"></div><button class="btn btn-primary" type="submit">Save</button></form><div style="overflow:auto"><table class="module-table"><thead id="head"></thead><tbody id="body"><tr><td>Loading...</td></tr></tbody></table></div></section></main></div></div><script>
const M='<?=e($module)?>',API='/api.php',CSRF='<?=e($csrf)?>'; const $=id=>document.getElementById(id); const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const configs={
 trainers:{action:'trainers',create:'create_trainer',cols:['full_name','email','specialization','experience_years','hourly_rate','status'],fields:[['name','Name'],['email','Email'],['specialization','Specialization'],['experience_years','Experience (years)'],['hourly_rate','Hourly rate'],['bio','Bio']]},
 memberships:{action:'plans',create:'create_plan',cols:['title','tag','price','billing_cycle','duration_days','status'],fields:[['title','Plan title'],['tag','Tag'],['price','Price'],['billing_cycle','Cycle'],['duration_days','Duration days'],['description','Description']]},
 attendance:{action:'attendance',create:'check_in',cols:['full_name','email','date','check_in_time','check_out_time','status'],fields:[['member_id','Member ID'],['status','Status']]},
 payments:{action:'payments',create:'create_payment',cols:['full_name','amount','payment_method','transaction_id','status','payment_date'],fields:[['member_id','Member ID'],['amount','Amount'],['payment_method','Method'],['transaction_id','Transaction ID'],['status','Status']]},
 workouts:{action:'workouts',create:'create_workout',cols:['title','member_name','trainer_name','goal','start_date','end_date'],fields:[['member_id','Member ID'],['trainer_id','Trainer ID'],['title','Workout title'],['goal','Goal'],['start_date','Start date'],['end_date','End date']]},
 reports:{action:'reports',create:null,cols:[],fields:[]}
}; const C=configs[M];
function fields(){ $('fields').innerHTML=C.fields.map(([n,l])=>`<label>${esc(l)}<input name="${n}" ${n.includes('date')?'type="date"':''} required></label>`).join('') }
async function load(){let url=API+'?action='+C.action+(M==='attendance'?'&date='+new Date().toISOString().slice(0,10):''); if($('search').value)url+='&q='+encodeURIComponent($('search').value);const r=await fetch(url);const j=await r.json();if(!j.success){$('body').innerHTML='<tr><td>'+esc(j.message)+'</td></tr>';return}let d=j.data;if(M==='reports'){renderStats(d);$('head').innerHTML='';$('body').innerHTML='<tr><td>Operational report metrics are shown above. Use the other modules to maintain source data.</td></tr>';return}d=Array.isArray(d)?d:[];$('head').innerHTML='<tr>'+C.cols.map(c=>'<th>'+esc(c.replaceAll('_',' '))+'</th>').join('')+'</tr>';$('body').innerHTML=d.length?d.map(x=>'<tr>'+C.cols.map(c=>'<td>'+esc(x[c])+'</td>').join('')+'</tr>').join(''):'<tr><td colspan="10">No records found.</td></tr>';renderStats({[M]:d.length});}
function renderStats(d){$('stats').innerHTML=Object.entries(d).map(([k,v])=>`<div class="panel-card module-stat"><span>${esc(k.replaceAll('_',' '))}</span><strong>${typeof v==='number'&&k==='revenue'?'₹'+v.toFixed(2):esc(v)}</strong></div>`).join('')}
$('toggleForm').onclick=()=>{if(!C.create)return; $('form').style.display=$('form').style.display==='none'?'grid':'none';fields()};$('refresh').onclick=load;$('search').oninput=()=>{clearTimeout(window.st);window.st=setTimeout(load,250)};
$('form').onsubmit=async e=>{e.preventDefault();let fd=new FormData(e.target);let r=await fetch(API+'?action='+C.create,{method:'POST',body:fd});let j=await r.json();alert(j.message);if(j.success){e.target.reset();$('form').style.display='none';load()}};load();
</script><script src="/assets/js/main.js"></script><script src="/assets/js/dashboard.js"></script></body></html>